import json, html, re, datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BASE = "https://pulseorbit.github.io"
DATA = json.loads((ROOT / "posts/index.json").read_text(encoding="utf-8"))
POSTS = DATA.get("posts", [])

def esc(value):
    return html.escape(str(value or ""), quote=True)

def build_post(post):
    slug = re.sub(r"[^a-z0-9-]", "", post.get("slug", ""))
    if not slug:
        return None
    url = f"{BASE}/{slug}/"
    title = esc(post.get("title", "PulseOrbit story"))
    description = esc(post.get("description", ""))
    image = post.get("image", "/assets/images/placeholder.svg")
    if not str(image).startswith(("https://", "http://", "/")):
        image = "/" + str(image)
    image = esc(image)
    category = esc(post.get("category", "Insights"))
    date = esc(post.get("date", datetime.date.today().isoformat()))
    body = post.get("content_html", "")
    # The article body is generated by our publisher and escaped paragraph-by-paragraph.
    sources = "".join(f'<li><a href="{esc(s.get("url"))}" rel="nofollow noopener" target="_blank">{esc(s.get("title") or s.get("url"))}</a></li>' for s in post.get("sources", []) if s.get("url"))
    credit = esc(post.get("image_credit", ""))
    alt = esc(post.get("image_alt") or post.get("title"))
    schema = {"@context":"https://schema.org","@type":"Article","headline":post.get("title",""),"description":post.get("description",""),"datePublished":post.get("date",""),"dateModified":post.get("date",""),"author":{"@type":"Organization","name":"PulseOrbit"},"publisher":{"@type":"Organization","name":"PulseOrbit","url":BASE},"mainEntityOfPage":url,"image":image}
    ld = json.dumps(schema, ensure_ascii=False).replace("</", "<\\/")
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090e1b"><meta name="description" content="{description}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{url}"><link rel="alternate" hreflang="x-default" href="{url}"><meta property="og:site_name" content="PulseOrbit"><meta property="og:type" content="article"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:url" content="{url}"><meta property="og:image" content="{image}"><meta property="article:published_time" content="{date}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{title}"><meta name="twitter:description" content="{description}"><meta name="twitter:image" content="{image}"><title>{title} | PulseOrbit</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/css/style.css"><script defer src="/assets/js/config.js"></script><script defer src="/assets/js/app.js"></script><script type="application/ld+json">{ld}</script></head><body data-post-slug="{esc(slug)}"><header class="site-header"><a class="brand" href="/"><span class="brand-mark">P</span><span>Pulse<span class="brand-light">Orbit</span></span></a><nav class="desktop-nav"><a href="/#latest" data-i18n="latest">Latest</a><a href="/#sponsor" data-i18n="sponsor">Sponsor</a></nav><div class="header-actions"><label class="language-wrap"><span class="sr-only">Language</span><select id="languageSelect" aria-label="Select language"><option value="en">EN</option><option value="bn">বাংলা</option></select></label><button class="icon-btn" id="themeToggle" aria-label="Toggle theme">◐</button></div></header><main><article class="article-view"><a class="back-link" href="/" data-i18n="back">← BACK TO PULSEORBIT</a><div class="story-meta" style="margin-top:28px"><span class="story-category">{category}</span><span>•</span><time datetime="{date}">{date}</time><span>•</span><span>{esc(post.get("read_time","4 min read"))}</span></div><h1>{title}</h1><p class="article-deck">{description}</p><img class="article-hero" src="{image}" alt="{alt}" fetchpriority="high"><div class="article-tools"><button id="nativeShare" type="button" data-i18n="share">Share story ↗</button><button id="copyShare" type="button" data-i18n="copy">Copy link</button><span class="view-count" id="viewCount">Views: connecting…</span></div><div class="article-body">{body}</div><div class="article-sources"><strong>Sources & image credits</strong><ul>{sources}</ul>{f"<p>Image: {credit}</p>" if credit else ""}</div></article></main><footer class="site-footer wrap"><div class="footer-top"><a class="brand" href="/"><span class="brand-mark">P</span><span>Pulse<span class="brand-light">Orbit</span></span></a><div class="footer-links"><a href="/#latest">Latest</a><a href="/#sponsor">Sponsor</a><a href="mailto:support@ahyancreations.top" data-i18n="contact">Contact</a></div></div><div class="footer-bottom"><div><strong>PulseOrbit</strong><p>Rajshahi, Bangladesh · <a href="mailto:support@ahyancreations.top">support@ahyancreations.top</a></p><p class="credit-line">Website crafted and maintained by <strong>Ahyan</strong>.</p></div><span>© PulseOrbit. Stay curious.</span></div></footer></body></html>'''

def main():
    urls = [BASE + "/"]
    for post in POSTS:
        page = build_post(post)
        if not page:
            continue
        slug = re.sub(r"[^a-z0-9-]", "", post["slug"])
        folder = ROOT / slug
        folder.mkdir(parents=True, exist_ok=True)
        (folder / "index.html").write_text(page, encoding="utf-8")
        urls.append(f"{BASE}/{slug}/")
    entries = "".join(f"<url><loc>{html.escape(url)}</loc></url>" for url in urls)
    sitemap = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + entries + '</urlset>\n'
    (ROOT / "sitemap.xml").write_text(sitemap, encoding="utf-8")
    print(f"Built {len(urls)-1} article pages and sitemap with {len(urls)} URLs.")

if __name__ == "__main__":
    main()
